import matplotlib.pyplot as plt
D=Path('/data/humanoid-sitting-perception/low_seat_contact_01');O=D/'progress_report_324'
read=lambda p:json.loads(Path(p).read_text());sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def table(head,rows):
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def fmt(x):return 'unavailable' if x is None else f'{x:.6g}' if isinstance(x,float) else x
def main():
 r=read(D/'finite_contact_diagnosis_322/results.json');a=read(D/'finite_contact_audit_323/independent_audit.json');assert a['passed'];O.mkdir(exist_ok=False)
 sel=[z for z in r['rows'] if z['case']<2 and z['window'][0]==11.];labels=[f"Case {z['case']} / {z['side']}" for z in sel];x=np.arange(4)
 plt.rcParams.update({'font.size':11,'axes.spines.top':False,'axes.spines.right':False})
 fig,axes=plt.subplots(1,2,figsize=(12,5.6),layout='constrained')
 for off,key,label,color in [(-.18,'weighted_normal_velocity','Load-weighted endpoint velocity','#275d8a'),(.18,'weighted_normal_fd','Same-material pose difference','#c0732b')]:
  axes[0].bar(x+off,[z['metrics'][key]['median']*1000 for z in sel],.36,label=label,color=color)
 axes[0].set_ylabel('Median normal component (mm/s)');axes[0].set_title('Different recorded sampling quantities');axes[0].set_xticks(x,labels,rotation=20,ha='right');axes[0].legend(loc='upper center',bbox_to_anchor=(.5,-.28),fontsize=9)
 axes[1].bar(x,[100*z['force_weighted_positive_velocity_fraction'] for z in sel],color='#275d8a');axes[1].set_ylim(0,100);axes[1].set_ylabel('Normal load at positive endpoint velocity (%)');axes[1].set_title('Reported load spans both velocity signs');axes[1].set_xticks(x,labels,rotation=20,ha='right')
 for ax in axes:ax.grid(axis='y',alpha=.2)
 fig.suptitle('Finite contact assessment — selected hover, 11–13 s\nNo per-stage impulse or complementarity certificate',fontsize=14);fig.savefig(O/'finite_support.png',dpi=160);plt.close(fig)
 fig,axes=plt.subplots(1,2,figsize=(12,5.7),layout='constrained')
 for off,key,label,color in [(-.18,'normal_force_endpoint_pairing','Reported force × endpoint velocity','#275d8a'),(.18,'normal_force_material_fd_pairing','Reported force × material pose difference','#c0732b')]:
  axes[0].bar(x+off,[z['metrics'][key]['median'] for z in sel],.36,label=label,color=color)
 axes[0].set_ylabel('Median sum of pairings (N·m/s)');axes[0].set_title('These are NOT measured power or work');axes[0].legend(loc='upper center',bbox_to_anchor=(.5,-.28),fontsize=9)
 axes[1].bar(x,[z['metrics']['friction_norm_sum_over_normal']['median'] for z in sel],color='#627e56');axes[1].set_ylabel('Sum |reported friction force| / sum normal force');axes[1].set_title('Descriptive ratio — NOT capacity utilization')
 for ax in axes:ax.set_xticks(x,labels,rotation=20,ha='right');ax.grid(axis='y',alpha=.2)
 fig.suptitle('Do not infer dissipation or friction capacity from unaligned returns',fontsize=14);fig.savefig(O/'contact_pairings.png',dpi=160);plt.close(fig)
 flat=[]
 for row in r['rows']:
  m=row['metrics'];flat.append(dict(case=row['case'],side=row['side'],window=str(row['window']),samples=row['samples'],floor_only=row['observed_floor_only'],external_incomplete=row['external_set_incomplete'],loaded_points_median=m['loaded_points']['median'],normal_rank_min=m['normal_rank']['min'],normal_rank_max=m['normal_rank']['max'],normal_force_median_N=m['normal_force']['median'],weighted_vn_median_m_s=m['weighted_normal_velocity']['median'],weighted_pose_fd_median_m_s=m['weighted_normal_fd']['median'],reported_gap_weighted_median_m=m['weighted_separation']['median'],positive_velocity_load_fraction=row['force_weighted_positive_velocity_fraction'],positive_gap_load_fraction=row['force_weighted_positive_gap_fraction'],friction_ratio_median=m['friction_norm_sum_over_normal']['median']))
 with (O/'all_case_windows.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(flat[0]));w.writeheader();w.writerows(flat)
 alltab=table(list(flat[0]),[[fmt(v) for v in z.values()] for z in flat])
 selectedtab=table(['Case / foot','Loaded points / normal rank','Normal force N','Weighted vₙ mm/s','Weighted query gap µm','Positive-velocity load %','Friction norm ratio'],[[f"{z['case']} / {z['side']}",'4 / 3',fmt(z['metrics']['normal_force']['median']),fmt(z['metrics']['weighted_normal_velocity']['median']*1000),fmt(z['metrics']['weighted_separation']['median']*1e6),fmt(z['force_weighted_positive_velocity_fraction']*100),fmt(z['metrics']['friction_norm_sum_over_normal']['median'])] for z in sel])
 src='https://github.com/NVIDIA-Omniverse/PhysX/blob/fc1018a3745664a1db2b95ce03fb5e91eb585f2e/physx/source/gpusolver/src/CUDA/'
 missing=table(['Available recording','Still unavailable'],[['End-of-step normal force, point, normal and separation','Prepared rest-distance correction, bias coefficient, minPen/maxPenBias and stage displacement'],['Separate friction force and application point','Friction patch IDs, paired axes, anchor errors and broken flags'],['End-of-step link/joint velocity and target','Velocity before each internal contact/drive row and accumulated stage impulse'],['Configured materials and authored iteration settings','Actual combined patch coefficients, effective island counts, traversal and CFM response columns'],['Pinned public source family','Installed GPU binary equivalence']])
 body=f'''<!doctype html><html><head><meta charset="utf-8"><title>Finite contact assessment 324</title><style>body{{font:18px/1.55 system-ui;max-width:1280px;margin:30px auto;padding:0 24px;color:#203040}}h1{{font-size:34px}}h2{{margin-top:34px}}.notice{{background:#fff2dd;padding:18px;border-left:5px solid #ac6925}}img,video{{max-width:100%}}.scroll{{overflow:auto}}table{{border-collapse:collapse;font-size:13px}}th,td{{padding:7px;border:1px solid #cbd2dc;white-space:nowrap}}th{{background:#edf1f5}}a{{color:#176798}}</style></head><body>
<h1>Finite contacts do not supply a verified drive/contact predictor</h1>
<p class="notice"><b>Repair remains unfinished. Best verified controller: 64/72 clean, 70 stable, eight slipping and two housing-contact cases.</b> All 64 successes remain protected. This round adds zero physics, settling, full-duration episodes or optimizer updates. PPO and the fresh holdout remain unstarted. No runtime, guard, material, solver setting or physical criterion changed.</p>
<h2>What the existing recordings establish</h2><p>The assessment covers all 1,000 saved intervals from 8.005–13 s, 24 cases and two feet: 48,000 foot intervals, {r['normal_point_records']:,} normal-point records and {r['friction_point_records']:,} friction-point records. All original zero-force points remain included. Separate normal and friction points are never paired by array index. The observed floor-only label is true for 34,288 foot intervals; the other 13,712 remain marked as having an incomplete whole-body external-contact set. Their available foot records remain reported.</p>
<p>At 11–13 s, each selected foot has four loaded normal points and two reported friction points. The four scaled normal constraint rows have rank three; this is different from imposing six bilateral stationary-sole constraints. It does not identify the friction constraints or prove that a new controller is feasible. Every selected normal return is nonnegative, but reported load is present at both signs of endpoint normal velocity. Positive-velocity points carry about 44.3–44.4% of left-foot load and 14.9% of right-foot load.</p>
{selectedtab}<img src="finite_support.png" alt="Load weighted normal velocities and positive velocity load fractions">
<p>Load-weighted normal endpoint velocity medians are −5.67 to −6.34 mm/s. Same-material pose-difference medians are near zero (about −0.00161 to +0.00160 mm/s). These are different sampling quantities, not evidence that a sensor is defective or permission to replace raw velocity. The raw settling contract remains unchanged.</p>
<p>The load-weighted <em>reported query separation</em> is +1.61 to +1.71 µm, although an unweighted point summary can be negative. About 69.6–83.2% of load is assigned to positive reported gaps. Contact/rest offsets and internal prepared separations are not recorded; this does not establish illegal contact, levitation, an offset value or a changed physical label.</p>
<h2>Normal and friction timing cannot be recovered from these returns</h2><p>The installed query API explicitly divides contact impulses by the requested time step, here 5 ms. Multiplying by 5 ms restores the reported aggregate impulse, not its distribution across internal iterations. The source uses a unilateral, bounded normal impulse and finite friction constraints with evolving separation and anchor errors. A returned impulse paired with final velocity is not a per-stage complementarity test.</p>
<p>For the selected feet, sum of reported friction-force magnitudes divided by total scalar normal force has medians 0.00610–0.01157. This is a descriptive demand ratio, <b>not friction utilization, capacity or proof of sticking</b>. No combined friction coefficient or patch assignment is inferred. Pairing normal force with endpoint velocity gives medians around −0.90 to −1.00 N·m/s; pairing the same force with material pose differences gives values near zero. Neither is measured dissipated power or valid integrated contact work. Friction pairings likewise need not have the same sign when sampled differently.</p>
<img src="contact_pairings.png" alt="Force velocity pairings differ by sampled velocity definition; friction ratio is descriptive">
<h2>Pinned primary source and unavailable state</h2><p>The read-only bundle pins NVIDIA PhysX commit <code>fc1018a3745664a1db2b95ce03fb5e91eb585f2e</code>, tag 110.0 / PhysX 5.8.0. Installed extension 110.3.2 is not proven identical. <a href="{src}solverMultiBlockTGS.cu#L916">The articulation contact call</a> dispatches to <a href="{src}solver.cuh#L421">solveExtContactBlockTGS</a>. The normal update includes response plus CFM, current stage velocity, separation and accumulated spatial motion, bias and impulse bounds. <a href="{src}solver.cuh#L556">The friction update</a> uses normal impulse, paired tangential directions, static/dynamic bounds and cached anchor drift. These observations describe the public algorithm family, not captured installed GPU internals.</p>{missing}
<p>No missing parameter was fitted, silently set to zero or replaced by contact truth in a controller. No finite-contact forward simulation or new control command was selected. The earlier ordered ideal-sole model remains rejected. These data cannot uniquely reconstruct its missing finite-contact stages; this is a limit of this reconstruction, not impossibility of another sitting transition.</p>
<h2>Independent audit</h2><p>Audit 323 rebuilt every foot interval directly from the original normal/friction query slices, manually expanded quaternion rotations and cross products, and independently summed and sorted statistics. All {a['checks']:,} checks passed, including {a['statistic_checks']:,} summary checks across 96 case/foot windows. Maximum arithmetic difference was {max(a['maximum_errors'].values()):.6g} under the predeclared 1e−9 numerical bound. All source hashes and counts match. The 1e−10 rank threshold is numerical only; no physical or quiet threshold changed. <a href="independent_audit.json">Full audit</a>.</p>
<p>No calculation, audit or physics recovery was needed. The initial SSH source-fetch attempt was blocked locally before remote execution, then succeeded through authorized SSH access. One read-only script inspection omitted the project working directory and exited without changing a file. All completed historical results remain intact.</p>
<h2>Next design requirement</h2><p>Before using a finite-contact model for a new command, establish its prepared contact parameters and state availability from source and existing artifacts. CFM/effective response, rest-distance bias and per-stage friction/drive ordering must remain explicitly unknown unless independently established. Do not fit them from these endpoint forces to force a match. A bounded alternate approach remains open research; preserve the whole-path support/clearance, existing command authority/filter/rate, current input validity, 164 balance, 207 bias and 175/130 quiet/load guards. No new physical launch follows this arithmetic audit.</p>
<h2>All case and foot windows</h2>{alltab}<p><a href="all_case_windows.csv">All 96 rows as CSV</a> · <a href="results.json">Full statistics and scope</a> · <a href="context.json">Source context and unknowns</a></p>
<h2>Physical outcomes and effort remain unchanged</h2><p>Latest full-duration probe 273 remains rejected: 20 stable, 14 clean, eight slipping, two hip-housing/physical failures, zero illegal-patch cases and 19 conservative warnings. Selected cases 0/1 still hover with zero quiet release, legal seat load and seated hold. No-slip hovering is not sitting. All eight target conditions remain unresolved; no 72-case retention followed. The other centered geometries still fail the 3 mm model clearance screen. All eight failures must be removed and all 64 successes retained across 72 matched full 20 s trials before PPO.</p>
<p>No new effort result. Probe 273 versus bestnormal3s on 14 common complete clean trials: whole-20 s torque² +0.0126472%, final-10 s +0.0264487%, final-5 s +0.0794278%; strict-both subset only one trial. These unselected-success differences do not establish repair or savings. Applied torque is approximate implicit-PD telemetry, not isolated solver/hardware effort, energy or a global optimum. Failed hovers and prefixes are excluded.</p>
<h2>Complete video remains current</h2><p>No new recorded motion. The unchanged 58.4 s video covers 44 recorded sources: 864 complete trials (503 clean, 361 failed), 192 diagnostic prefixes and 120 aborted case attempts without saved motion explicitly disclosed. It is a recorded XYZW link-pose schematic with model head COM, not camera footage. 0.1 s poses bracket 0.02 s event labels. Historical totals are not best-controller accuracy.</p><video controls preload="metadata" src="../all_attempts_video_307/all_attempts.mp4"></video>
</body></html>'''
 (O/'findings.html').write_text(body)
 for source,name in [('finite_contact_diagnosis_322/results.json','results.json'),('finite_contact_audit_323/independent_audit.json','independent_audit.json'),('finite_contact_revision_322.json','revision.json'),('finite_contact_source_321/source_manifest.json','source_manifest.json'),('finite_contact_source_321/context.json','context.json')]:shutil.copy2(D/source,O/name)
